package service;
import dao.support.ServiceFixture;import model.*;import java.math.BigDecimal;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class ClearanceServiceTest {
    private ServiceFixture store;private AuthService auth;private ClearanceService service;private Session admin,officer,student;
    @BeforeEach void setup()throws Exception{store=new ServiceFixture();auth=new AuthService(store,12);service=new ClearanceService(store,auth);admin=store.login(auth,Role.ADMIN);officer=store.login(auth,Role.OFFICER);student=store.login(auth,Role.STUDENT);}
    private ClearanceRow row()throws Exception{return service.find(admin,"TEST-100",1).getFirst();}
    @Test void absentDecisionIsPendingAndStudentsCannotWrite()throws Exception{var row=row();assertEquals(ClearanceStatus.PENDING,row.status());assertThrows(AuthorizationException.class,()->service.decide(student,row,new ClearanceDraft(ClearanceStatus.CLEARED,null,false,null)));}
    @Test void blocksDebtWithoutReasonedAdminException()throws Exception{store.balance=new BigDecimal("50.00");var row=row();assertThrows(ValidationException.class,()->service.decide(admin,row,new ClearanceDraft(ClearanceStatus.CLEARED,null,false,null)));assertThrows(AuthorizationException.class,()->service.decide(officer,row,new ClearanceDraft(ClearanceStatus.CLEARED,null,true,"Officer denied")));assertThrows(ValidationException.class,()->service.decide(admin,row,new ClearanceDraft(ClearanceStatus.CLEARED,null,true," ")));}
    @Test void approvesAdminExceptionAndHoldRemovesItsMetadata()throws Exception{store.balance=new BigDecimal("50.00");var cleared=service.decide(admin,row(),new ClearanceDraft(ClearanceStatus.CLEARED,null,true,"Approved support"));assertTrue(cleared.record().balanceException());assertEquals(1,cleared.record().exceptionBy());var held=service.decide(admin,cleared,new ClearanceDraft(ClearanceStatus.ON_HOLD,"Review",false,null));assertFalse(held.record().balanceException());assertNull(held.record().exceptionReason());assertNull(held.record().clearedAt());}
    @Test void rejectsChangedBalanceAndChangedRecord()throws Exception{var original=row();store.balance=new BigDecimal("1.00");assertThrows(RecordChangedException.class,()->service.decide(admin,original,new ClearanceDraft(ClearanceStatus.CLEARED,null,true,"Changed balance")));store.balance=new BigDecimal("0.00");service.decide(admin,original,new ClearanceDraft(ClearanceStatus.CLEARED,null,false,null));assertThrows(RecordChangedException.class,()->service.decide(admin,original,new ClearanceDraft(ClearanceStatus.ON_HOLD,"Stale",false,null)));}
    @Test void requiresHoldReasonAndRejectsUnneededException()throws Exception{var row=row();assertThrows(ValidationException.class,()->service.decide(admin,row,new ClearanceDraft(ClearanceStatus.ON_HOLD," ",false,null)));assertThrows(ValidationException.class,()->service.decide(admin,row,new ClearanceDraft(ClearanceStatus.CLEARED,null,true,"No debt")));}
}
